package org.thingsboard.mqtt.broker.cache;

import lombok.Data;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.cache.Cache;
import org.springframework.cache.CacheManager;
import org.springframework.stereotype.Component;

@Component
@Data
public class CacheNameResolver {

    private final CacheManager cacheManager;

    @Value("${cache.cache-prefix:}")
    private String cachePrefix;

    public Cache getCache(String cacheName) {
        return cacheManager.getCache(cachePrefix + cacheName);
    }

}
```
This is the canonical wrapper bean around `CacheManager`. It is a `@Component` holding the `CacheManager`, and `getCache(cacheName)` prepends a configurable `cache.cache-prefix` before delegating to `cacheManager.getCache(...)`.

